// ----------------------------------------------------------------
// Word (.docx) export — fills a Word template with one meeting's data so
// officers can download an editable agenda and adjust it in Word.
//
// The template is the club's own upload (clubs.settings.word_template_url)
// or the bundled default (public/templates/agenda-default.docx, generated by
// scripts/build-word-template.mjs). Templates mark fields with {{標記}}; loops
// repeat a table row: {{#演講}} … {{/演講}} placed in the cells of one row.
//
// WORD_FIELDS is the single list of supported marks: the club modal's help,
// the upload check (unknown marks) and the README all come from it.
// ----------------------------------------------------------------
import { withBase } from './basePath';

export const WORD_DEFAULT_TEMPLATE = withBase('/templates/agenda-default.docx');
export const WORD_DELIMITERS = { start: '{{', end: '}}' };

// [mark, description]. Loops list their own inner marks.
export const WORD_FIELDS = {
  分會資訊: [
    ['分會名稱', '中文名稱（沒填則用分會名稱）'], ['分會英文名稱', '英文名稱'], ['分會編號', 'Club Number'],
    ['分會網站', '分會網站'], ['例會時間說明', '例會時間說明（中文）'],
  ],
  例會資訊: [
    ['例會日期', '例如 2026.11.04'], ['例會次數', '第幾次例會'], ['例會主題', '主題'],
    ['時間', '例會時間'], ['地點', '地點（可多行）'],
  ],
  角色: [
    ['接待', '報到接待'], ['宣布開會', '宣布例會開始'], ['會長致詞', '會長致歡迎詞'], ['總主持人', '總主持人 TME'],
    ['計時員', '計時員'], ['贅語記錄員', '贅語記錄員'], ['即席主持人', '即席問答主持人'], ['總講評', '總講評'],
    ['語言講評', '語言講評'], ['頒獎人', '贈感謝狀'], ['分享回饋', '會後分享 & 來賓回饋'],
  ],
  時間點: [
    ['報到時間', ''], ['開場時間', ''], ['多元單元時間', ''], ['演講時間', ''], ['合照時間', ''],
    ['即席時間', ''], ['講評時間', ''], ['閉幕時間', ''], ['分享時間', ''], ['休息分鐘', '中場休息幾分鐘'],
  ],
  幹部: [
    ['會長', ''], ['教育副會長', ''], ['會員副會長', ''], ['公關副會長', ''],
    ['秘書', ''], ['財務長', ''], ['事務長', ''],
  ],
};
export const WORD_LOOPS = {
  演講: { desc: '每位指定演講者一列', fields: [['序號', '1、2、3…'], ['講題', ''], ['講者', ''], ['時長', "例如 5'-7'"], ['專案', 'Pathways 專案（有填才有）']] },
  講評員: { desc: '每位個別講評員一列', fields: [['序號', ''], ['姓名', ''], ['講者', '被講評的講者']] },
  講評員講評: { desc: '每位講評員講評一列（沒有就整列消失）', fields: [['序號', ''], ['姓名', '']] },
  多元單元: { desc: '有開多元單元才出現的列', fields: [['主持人', ''], ['時間', '']] },
};

const OFFICER_KEYS = {
  會長: 'officer_president', 教育副會長: 'officer_vpe', 會員副會長: 'officer_vpm', 公關副會長: 'officer_vppr',
  秘書: 'officer_secretary', 財務長: 'officer_treasurer', 事務長: 'officer_saa',
};

/** Every mark a template may use (scalars, loop names and loop-inner marks). */
export function wordKnownTags() {
  const tags = new Set(Object.values(WORD_FIELDS).flat().map(([k]) => k));
  Object.entries(WORD_LOOPS).forEach(([loop, { fields }]) => {
    tags.add(loop);
    fields.forEach(([k]) => tags.add(k));
  });
  return tags;
}

/**
 * The values a template is filled with. `ctx` carries the agenda page's own
 * helpers so names and times come out exactly as on the printed agenda:
 * { times (calcTimes()), displayMember, formatDate, varietySession, pathwayLabel }.
 */
export function buildWordData(data, club, ctx) {
  const { times, displayMember, formatDate, varietySession, pathwayLabel } = ctx;
  const set = (club && club.settings) || {};
  const who = (v) => displayMember(v) || '';
  const speeches = (data.speeches || []).filter((sp) => sp.title || sp.speaker);
  const out = {
    分會名稱: (club && (club.name_zh || club.name)) || '',
    分會英文名稱: (club && club.name_en) || '',
    分會編號: (club && club.charter_no) || '',
    分會網站: set.website || '',
    例會時間說明: set.scheduleZh || '',
    例會日期: data.meetingDate ? formatDate(data.meetingDate) : '',
    例會次數: data.meetingNo || '',
    例會主題: data.meetingTheme || '',
    時間: data.timeRange || '',
    地點: data.venueInfo || '',
    接待: who(data.receptionHost),
    宣布開會: who(data.callingToOrder),
    會長致詞: who(data.welcomeTME),
    總主持人: who(data.tme),
    計時員: who(data.timer),
    贅語記錄員: who(data.ahCounter),
    即席主持人: who(data.tableTopicsMaster),
    總講評: who(data.generalEvaluator),
    語言講評: who(data.langEvaluator),
    頒獎人: who(data.awardsPresenter),
    分享回饋: who(data.sharingFeedback),
    報到時間: times.receptionStart,
    開場時間: times.openingStart,
    多元單元時間: varietySession.enabled ? times.speechStart : '',
    演講時間: times.preparedSpeechStart,
    合照時間: times.photoStart,
    即席時間: times.topicsStart,
    講評時間: times.evalStart,
    閉幕時間: times.closingStart,
    分享時間: times.sharingStart,
    休息分鐘: String(times.intermissionMins),
    演講: speeches.map((sp, i) => ({
      序號: String(i + 1), 講題: sp.title || '', 講者: who(sp.speaker),
      時長: sp.duration || "5'-7'", 專案: pathwayLabel ? pathwayLabel(sp) : '',
    })),
    講評員: (data.evaluators || []).map((ev, i) => ({
      序號: String(i + 1), 姓名: who(ev), 講者: speeches[i] ? who(speeches[i].speaker) : '',
    })),
    講評員講評: (data.evalEvaluators || []).filter(Boolean).map((ev, i) => ({ 序號: String(i + 1), 姓名: who(ev) })),
    // A one-item list (row shown) or empty (row removed).
    多元單元: varietySession.enabled ? [{ 主持人: who(varietySession.host), 時間: times.speechStart }] : [],
  };
  Object.entries(OFFICER_KEYS).forEach(([tag, key]) => { out[tag] = set[key] || ''; });
  return out;
}

async function loadEngine() {
  const [{ default: PizZip }, { default: Docxtemplater }] = await Promise.all([import('pizzip'), import('docxtemplater')]);
  return { PizZip, Docxtemplater };
}

// docxtemplater error ids → what to fix, in the club officer's words.
const ERROR_ZH = {
  unclosed_loop: (t) => `迴圈 {{#${t}}} 沒有對應的 {{/${t}}}`,
  unopened_loop: (t) => `{{/${t}}} 前面沒有對應的 {{#${t}}}`,
  closing_tag_does_not_match_opening_tag: (t) => `迴圈的開頭與結尾標記不一致（${t}）`,
  unclosed_tag: (t) => `標記 {{${t} 缺少結尾的 }}`,
  unopened_tag: (t) => `標記 ${t}}} 缺少開頭的 {{`,
  duplicate_open_tag: (t) => `標記開頭重複了 {{（${t}）`,
  duplicate_close_tag: (t) => `標記結尾重複了 }}（${t}）`,
};

/** Readable list of a docxtemplater error's problems (bad / unclosed marks). */
export function wordTemplateErrors(e) {
  const list = (e && e.properties && e.properties.errors) || [e];
  return list.map((err) => {
    const p = err.properties || {};
    const tag = p.xtag || '';
    if (ERROR_ZH[p.id]) return ERROR_ZH[p.id](tag);
    return tag ? `${p.explanation || err.message}（${tag}）` : (p.explanation || err.message);
  });
}

/**
 * Check an uploaded template before it is saved. Returns
 * { errors: [..] (template unusable), unknown: [..] (marks we don't fill) }.
 */
export async function checkWordTemplate(arrayBuffer) {
  const { PizZip, Docxtemplater } = await loadEngine();
  // docxtemplater calls `parser` once per mark (loop names included) while it
  // compiles the template, which is all we need to list the marks used.
  const used = new Set();
  const parser = (tag) => { used.add(tag.trim()); return { get: (scope) => (scope ? scope[tag] : undefined) }; };
  try {
    new Docxtemplater(new PizZip(arrayBuffer), {
      paragraphLoop: true, linebreaks: true, delimiters: WORD_DELIMITERS, parser, errorLogging: false,
    });
  } catch (e) {
    return { errors: wordTemplateErrors(e), unknown: [] };
  }
  const known = wordKnownTags();
  return { errors: [], unknown: [...used].filter((k) => !known.has(k)) };
}

/** Fill `arrayBuffer` (a .docx) with `values`; resolves to a .docx Blob. */
export async function fillWordTemplate(arrayBuffer, values) {
  const { PizZip, Docxtemplater } = await loadEngine();
  const doc = new Docxtemplater(new PizZip(arrayBuffer), {
    paragraphLoop: true, linebreaks: true, delimiters: WORD_DELIMITERS,
    nullGetter: () => '', // a mark with no value prints nothing, not "undefined"
  });
  doc.render(values);
  return doc.getZip().generate({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  });
}
